-- NovaShop initial Supabase schema. Safe to keep in version control.
-- Never put service_role or secret keys in SQL files or browser code.
create extension if not exists pgcrypto;

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text not null default '',
  phone text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.products (
  id integer primary key,
  name text not null,
  category text not null,
  price_cop bigint not null check (price_cop > 0),
  delivery_type text not null default 'physical' check (delivery_type in ('physical','digital')),
  is_active boolean not null default true,
  updated_at timestamptz not null default now()
);

